<?php
require dirname(__DIR__).'/_init.php';use App\Core\AccessControl;use App\Core\Database;
AccessControl::require('consultations.manage');$rows=Database::connection()->query("SELECT a.id,a.appointment_date,a.appointment_time,p.patient_number,p.full_name,d.name doctor_name FROM appointments a JOIN patients p ON p.id=a.patient_id JOIN doctors d ON d.id=a.doctor_id WHERE a.status='checked_in' ORDER BY a.appointment_time")->fetchAll();require dirname(__DIR__).'/_layout_top.php';?>
<h2>Patients awaiting consultation</h2><div class="card p-3 table-responsive"><table class="table"><thead><tr><th>Patient</th><th>Doctor</th><th>Appointment</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['patient_number'].' - '.$r['full_name'])?></td><td><?=e($r['doctor_name'])?></td><td><?=e($r['appointment_date'].' '.$r['appointment_time'])?></td><td><a class="btn btn-sm btn-primary" href="/consultations/create.php?id=<?=$r['id']?>">Consult</a></td></tr><?php endforeach;?></tbody></table></div><?php require dirname(__DIR__).'/_layout_bottom.php';?>
